use crate::post_fixture::PostFixture;
use super::*;
use semio_framework_value::retirement::RetireOwned;
pub(super) fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
pub(super) const UNITS:u64=1<<20;
use protocol::{RetainedDiffOwner,RetainedDiffPreflightStep};
use semio_framework_value::{NativeDecodeControl,RetainedWorkPoll};
use semio_framework_value_clone_source_testing::{FixtureSource,drive::{drive,drive_reply}};
pub(super) fn source<T:RetireOwned+Sync+'static>(value:T)->FixtureSource<T>{FixtureSource::from_owner(value)}
pub(super) fn close_source<T:RetireOwned+Sync+'static>(owner:&mut FixtureSource<T>){for _ in 0..1000000{if owner.terminal_is_empty(){return}owner.close_once().unwrap_or_else(|_|panic!("source retirement refused"));}panic!("source retirement stalled")}
pub(super) fn preflight(owner:&mut RetainedDiffOwner<LayoutSnapshot,LayoutDiff>,diff:RetainedCloneRef<'_,LayoutDiff>,original:RetainedCloneRef<'_,LayoutSnapshot>,post:RetainedCloneRef<'_,LayoutSnapshot>,body:usize,g:RetainedCloneGrant,receiving:&mut NativeDecodeControl<'_>)->RetainedDiffPreflightStep{
 drive_reply::<RetainedDiffPreflightStep,OriginalRetirementFailure>(g,UNITS,|answer|match answer{Ok(step)=>step.progress(),Err(failure)=>failure.retained_progress()},|effect,reply:Reply<'_,RetainedDiffPreflightStep>,recover|->Result<Done<'_,RetainedDiffPreflightStep>,ValueError>{if recover{protocol::recover_preflight_retained_diff_into(owner,diff,original,post,body,UNITS,effect,&mut *receiving,reply)}else{protocol::preflight_retained_diff_into(owner,diff,original,post,body,UNITS,effect,&mut *receiving,reply)}}).result.unwrap_or_else(|_|panic!("original central preflight refused"))
}
pub(super) fn commit(owner:&mut RetainedDiffOwner<LayoutSnapshot,LayoutDiff>,diff:RetainedCloneRef<'_,LayoutDiff>,original:RetainedCloneRef<'_,LayoutSnapshot>,post:&mut PostFixture<LayoutSnapshot>,g:RetainedCloneGrant)->RetainedCloneStep{
 drive(g,UNITS,|effect|RetainedWorkPoll::Complete(protocol::commit_retained_diff(owner,diff,original,&mut *post,effect))).result.unwrap_or_else(|_|panic!("original central commit refused"))
}
pub(super) fn close_once(owner:&mut RetainedDiffOwner<LayoutSnapshot,LayoutDiff>,body:usize,g:RetainedCloneGrant)->RetainedCloneStep{
 drive_reply::<RetainedCloneStep,OriginalRetirementFailure>(g,UNITS,|answer|match answer{Ok(step)=>step.progress(),Err(failure)=>failure.retained_progress()},|effect,reply:Reply<'_>,recover|->Result<Done<'_>,ValueError>{if recover{owner.recover_close_into(body,effect,reply)}else{owner.close_into(body,effect,reply)}}).result.unwrap_or_else(|_|panic!("original central close refused"))
}
pub(super) fn close(owner:&mut protocol::RetainedDiffOwner<LayoutSnapshot,LayoutDiff>){owner.begin_close();for _ in 0..1000000{if owner.terminal_is_empty(){return}let d=owner.close_demand(65536).unwrap();assert_eq!(close_once(owner,65536,Default::default()).progress(),Default::default());let step=close_once(owner,65536,grant(d));assert!(step.progress().fits(grant(d)));if matches!(step,RetainedCloneStep::Complete(_)){assert!(owner.terminal_is_empty(),"child completion cannot settle the original parent")}}panic!("Layout retained original close stalled")}
fn decode<T:semio_framework_value::FromValue>(v:&serde_json::Value)->T{semio_framework_pack_json::from_json_str(&v.to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
#[test]
fn production_layout_retained_diff_matches_neutral_rfc6902_witnesses_without_post_clone(){let corpus:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../../../🧪️tests/🧫️fixtures/🧮️diff-algebra/🔣️.json")).unwrap();for case in corpus["cases"].as_array().unwrap(){let original:LayoutSnapshot=decode(&case["before"]);let expected:LayoutSnapshot=decode(&case["after"]);let event:LayoutDiff=decode(&case["diff"]);let mut post=PostFixture::new(original.clone());let untouched=post.stories.iter().map(|row|(row.id.clone(),row.content.as_ptr())).collect::<Vec<_>>();let mut base=source(original.clone());let mut diff=source(event.clone());let(mut owner,_)=protocol::begin_retained_diff::<LayoutSnapshot,LayoutDiff>(grant(protocol::retained_diff_birth_demand::<LayoutSnapshot,LayoutDiff>())).unwrap();let mut callback=|_|true;let mut receiving=semio_framework_value::NativeDecodeControl::new(1<<30,&mut callback);let mut admitted=false;for _ in 0..1000000{let d=owner.preflight_demand(diff.borrow(),base.borrow(),post.borrow(),65536,UNITS).unwrap();assert_eq!(preflight(&mut owner,diff.borrow(),base.borrow(),post.borrow(),65536,Default::default(),&mut receiving).progress(),Default::default());let step=preflight(&mut owner,diff.borrow(),base.borrow(),post.borrow(),65536,grant(d),&mut receiving);assert!(step.progress().fits(grant(d)));assert_eq!(post,original,"{}: read-only admission",case["name"]);if matches!(step,protocol::RetainedDiffPreflightStep::Admitted(..)){admitted=true;break}}assert!(admitted,"{}",case["name"]);post.mutable_read();let mut committed=false;for _ in 0..1000000{let d=owner.commit_demand(diff.borrow(),base.borrow(),&post,65536).unwrap();assert_eq!(commit(&mut owner,diff.borrow(),base.borrow(),&mut post,Default::default()).progress(),Default::default());let step=commit(&mut owner,diff.borrow(),base.borrow(),&mut post,grant(d));assert!(step.progress().fits(grant(d)));if matches!(step,RetainedCloneStep::Complete(_)){committed=true;break}}assert!(committed);assert_eq!(post,expected,"{}",case["name"]);if event.stories.is_none(){for(id,pointer)in untouched{assert_eq!(post.stories.iter().find(|row|row.id==id).unwrap().content.as_ptr(),pointer)}}assert_eq!(base.borrow().get(),&original);assert_eq!(diff.borrow().get(),&event);close(&mut owner);close_source(&mut diff);close_source(&mut base);let mut output=source(post.into_inner());close_source(&mut output)}}
#[test]
fn production_layout_retained_preflight_cancellation_closes_all_originals(){let corpus:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../../../🧪️tests/🧫️fixtures/🧮️diff-algebra/🔣️.json")).unwrap();for case in corpus["cases"].as_array().unwrap(){for cut in[0,1,8,32,128]{let original:LayoutSnapshot=decode(&case["before"]);let event:LayoutDiff=decode(&case["diff"]);let mut base=source(original.clone());let mut diff=source(event);let post=PostFixture::new(original.clone());let(mut owner,_)=protocol::begin_retained_diff::<LayoutSnapshot,LayoutDiff>(grant(protocol::retained_diff_birth_demand::<LayoutSnapshot,LayoutDiff>())).unwrap();let mut callback=|_|true;let mut receiving=semio_framework_value::NativeDecodeControl::new(1<<30,&mut callback);for _ in 0..cut{let d=owner.preflight_demand(diff.borrow(),base.borrow(),post.borrow(),65536,UNITS).unwrap();let step=preflight(&mut owner,diff.borrow(),base.borrow(),post.borrow(),65536,grant(d),&mut receiving);if matches!(step,protocol::RetainedDiffPreflightStep::Admitted(..)|protocol::RetainedDiffPreflightStep::Refused(..)){break}}assert_eq!(base.borrow().get(),&original);close(&mut owner);drop(post);close_source(&mut diff);close_source(&mut base)}}}
